pub proof fn always_implies_forall_intro<T, A>(spec: TempPred<T>, p: TempPred<T>, a_to_q: spec_fn(A) -> TempPred<T>)
    requires forall |a: A| #[trigger] spec.entails(always(p.implies(a_to_q(a)))),
    ensures spec.entails(always(p.implies(tla_forall(a_to_q)))),
{
    // spec.entails(X) == valid(spec.implies(X)) == forall ex, spec.satisfied_by(ex) ==> X.satisfied_by(ex)
    forall |ex: Execution<T>| {
        if spec.satisfied_by(ex) {
            // Need: always(p.implies(tla_forall(a_to_q))).satisfied_by(ex)
            assert
                forall |i: nat| #[trigger] (p.implies(tla_forall(a_to_q))).satisfied_by(ex.suffix(i))
            by {
                forall |i: nat| {
                    if p.satisfied_by(ex.suffix(i)) {
                        // Need: tla_forall(a_to_q).satisfied_by(ex.suffix(i))
                        assert
                            forall |a: A| #[trigger] a_to_q(a).satisfied_by(ex.suffix(i))
                        by {
                            forall |a: A| {
                                // From the premise: spec.entails(always(p.implies(a_to_q(a))))
                                assert spec.entails(always(p.implies(a_to_q(a))));
                                reveal spec.entails(always(p.implies(a_to_q(a))));

                                // So we have: forall ex2, spec.satisfied_by(ex2) ==> always(p.implies(a_to_q(a))).satisfied_by(ex2)
                                assert
                                    forall |ex2: Execution<T>| #[trigger]
                                        spec.satisfied_by(ex2) ==> always(p.implies(a_to_q(a))).satisfied_by(ex2);

                                // Instantiate ex2 = ex (current execution)
                                assert (spec.satisfied_by(ex) ==> always(p.implies(a_to_q(a))).satisfied_by(ex));
                                assert always(p.implies(a_to_q(a))).satisfied_by(ex);

                                // Unfold always at offset i
                                assert p.implies(a_to_q(a)).satisfied_by(ex.suffix(i));
                                assert a_to_q(a).satisfied_by(ex.suffix(i));
                            }
                        }
                    }
                }
            }
        }
    }
}

